INSERT INTO "tools" ("id","slug","no","name","grp","sub","pain","who","status","price","url","embed","videos","body","sort","visible","created_at","updated_at","pricing","price_note","featured","icon","tags","features","highlights","guide","version","released","author","download_url","banner_url") VALUES(8,'tra-cuu-van-ban','','Cẩm nang tra cứu Thuế – Kế toán – Lao động 2026','kt','Kế toán – tài chính','Không chắc văn bản nào còn hiệu lực, điều khoản nào đã bị sửa.','Kế toán, chủ doanh nghiệp nhỏ, người tự học thuế – kế toán','ok',0,'/tools/cam-nang-thue-2026/',0,'[]','',20,1,1791191469000,1791199063000,'free','',1,'book','Thuế, Kế toán, Lao động, Văn bản pháp luật',replace('Nghiên cứu theo 8 chủ đề kiến thức\nTủ văn bản pháp luật, mục lục Chương – Điều, mở toàn văn\nMáy tính thuế TNCN lũy tiến từng phần\nTra ngưỡng bắt buộc hóa đơn điện tử\nBảng tra thuế suất GTGT theo nhóm hàng\nChecklist tự rà soát rủi ro tuân thủ\nHỏi đáp nhanh\nĐánh dấu mục "Hay dùng" để mở lại nhanh','\n',char(10)),replace('Đối chiếu Luật – Nghị định – Thông tư | Xem song song quy định ở từng tầng văn bản, đến tận Chương, Điều.\nSo sánh trước & sau cải cách 2025-2026 | Thấy ngay điểm thay đổi của chính sách thuế để tránh áp dụng nhầm điều khoản cũ.\nCông cụ tính, tra tương tác | Máy tính thuế TNCN, tra ngưỡng hóa đơn điện tử, bảng thuế suất GTGT ngay trong trang.','\n',char(10)),replace('Bấm "Truy cập công cụ", cẩm nang mở ngay trên trình duyệt, không cần cài đặt hay đăng nhập.\nChọn cách tra: Đối chiếu văn bản, Nghiên cứu theo chủ đề, Tủ văn bản hoặc Công cụ tương tác ở menu bên trái.\nGặp điều khoản quan trọng, đối chiếu lại văn bản gốc mới nhất trước khi áp dụng cho số liệu chính thức.','\n',char(10)),'Nội dung cập nhật 08/2026','2026-10-05','Tuấn · Quản trị tử tế','','');
