INSERT INTO "legal_docs" ("id","source","docid","so_hieu","loai","co_quan","ngay_ban_hanh","ngay_bh_iso","hieu_luc","trich_yeu","url","pdf_url","list_name","score","level","topics","matched","reasons","title","summary","impact","action","ai","status","in_handbook","admin_note","found_at","approved_at","created_at","updated_at","key_points","full_text","recommend","recommend_note") VALUES(4,'chinhphu','219755','10065/VPCP-KGVX','Công văn','Văn phòng Chính phủ','02/10/2026','2026-10-02','','V/v phương án nghỉ một số dịp Lễ, Tết năm 2026 và năm 2027','https://chinhphu.vn/?pageid=27160&docid=219755','https://datafiles.chinhphu.vn/cpp/files/vbpq/2026/9/10065_vpcp-kgvx_02102026_1-signed.signed.pdf','Văn bản mới',35,'tb','hdld','','Từ khóa "nghỉ lễ, Tết" → HĐLĐ - Lao động','Phương án nghỉ Lễ, Tết 2026 – 2027: Tết Đinh Mùi nghỉ 7 ngày, Quốc khánh 2027 nghỉ 4 ngày','Văn phòng Chính phủ thông báo phương án nghỉ một số dịp Lễ, Tết năm 2026 và 2027 cho cơ quan nhà nước, doanh nghiệp và người lao động.','Chủ đề HĐLĐ – Lao động: phần thời giờ nghỉ ngơi, nghỉ lễ, Tết.','Bộ phận nhân sự cập nhật lịch nghỉ, chấm công và tính lương làm thêm giờ ngày lễ theo văn bản gốc.','BuBu (đọc toàn văn)','rejected',0,'',1791202673227,0,1791202673227,1791279832131,replace('Ngày Văn hóa Việt Nam năm 2026: nghỉ 1 ngày\nTết Âm lịch Đinh Mùi 2027: nghỉ 7 ngày\nLễ Quốc khánh 2027: nghỉ 4 ngày\nÁp dụng cho cơ quan hành chính, sự nghiệp, tổ chức chính trị – xã hội, doanh nghiệp và người lao động\nNgày nghỉ cụ thể và việc làm bù (nếu có): xem văn bản gốc','\n',char(10)),'','approve','Lịch nghỉ áp dụng cả doanh nghiệp, người lao động – liên quan chấm công, tính lương. Đã đọc toàn văn.');
