INSERT INTO "legal_docs" ("id","source","docid","so_hieu","loai","co_quan","ngay_ban_hanh","ngay_bh_iso","hieu_luc","trich_yeu","url","pdf_url","list_name","score","level","topics","matched","reasons","title","summary","impact","action","ai","status","in_handbook","admin_note","found_at","approved_at","created_at","updated_at","key_points","full_text","recommend","recommend_note") VALUES(67,'chinhphu','219739','43/2026/NQ-CP','Nghị quyết','Chính phủ','30/09/2026','2026-09-30','01/10/2026 – 31/12/2026','Về việc kéo dài thời hạn áp dụng thuế nhập khẩu ưu đãi, thuế bảo vệ môi trường, thuế giá trị gia tăng đối với mặt hàng xăng, dầu, nguyên liệu sản xuất xăng, dầu và nhiên liệu bay','https://chinhphu.vn/?pageid=27160&docid=219739','https://datafiles.chinhphu.vn/cpp/files/vbpq/2026/9/43_2026_nq-cp_30092026_1-signed.signed.pdf','Văn bản QPPL',55,'tb','gtgt','','Từ khóa "thuế giá trị gia tăng" → Thuế Giá trị gia tăng (GTGT) · Từ khóa "thuế bảo vệ môi trường" → Quản lý thuế chung · Nghị quyết Chính phủ (+10)','Kéo dài áp dụng thuế GTGT, thuế BVMT, thuế nhập khẩu ưu đãi với xăng dầu đến 31/12/2026','Chính phủ kéo dài thời hạn áp dụng thuế GTGT, thuế bảo vệ môi trường (theo Nghị quyết 19/2026/QH16) và thuế nhập khẩu ưu đãi với xăng, dầu, nguyên liệu sản xuất xăng dầu, nhiên liệu bay đến hết 31/12/2026.','Chủ đề Thuế GTGT: lưu ý thuế suất nhóm xăng dầu, nhiên liệu bay.','Doanh nghiệp kinh doanh hoặc dùng nhiều xăng dầu kiểm tra thuế suất GTGT trên hóa đơn đầu vào, đầu ra đến hết năm 2026.','BuBu (đọc toàn văn)','approved',0,'',1791202673227,1791279841124,1791202673227,1791279841124,replace('Kéo dài thuế GTGT, thuế BVMT với xăng, dầu, nguyên liệu sản xuất xăng dầu và nhiên liệu bay theo Nghị quyết 19/2026/QH16 đến 31/12/2026 (Điều 2)\nKéo dài thuế nhập khẩu ưu đãi với xăng, dầu, nguyên liệu sản xuất xăng dầu (theo NQ 25/2026/NQ-CP, NĐ 72/2026/NĐ-CP) đến 31/12/2026 (Điều 1)\nVăn bản không nêu lại mức thuế cụ thể – tiếp tục áp dụng mức đang hiện hành\nHiệu lực 01/10/2026 – 31/12/2026 (Điều 3)','\n',char(10)),'','approve','Liên quan thuế GTGT (chủ đề đã có) nhưng chỉ nhóm hàng xăng dầu → mức "Nên xem". Đã đọc toàn văn.');
