INSERT INTO "legal_docs" ("id","source","docid","so_hieu","loai","co_quan","ngay_ban_hanh","ngay_bh_iso","hieu_luc","trich_yeu","url","pdf_url","list_name","score","level","topics","matched","reasons","title","summary","impact","action","ai","status","in_handbook","admin_note","found_at","approved_at","created_at","updated_at","key_points","full_text","recommend","recommend_note") VALUES(93,'chinhphu','219657','21/2026/TT-BNV','Thông tư','Bộ Nội vụ','22/09/2026','2026-09-22','10/11/2026','Sửa đổi, bổ sung một số điều của Thông tư số 03/2020/TT-BLĐTBXH ngày 25 tháng 02 năm 2020 của Bộ trưởng Bộ Lao động - Thương binh và Xã hội hướng dẫn thực hiện chế độ, chính sách đối với cựu chiến binh theo quy định tại Nghị định số 157/2016/NĐ-CP ngày 24 tháng 11 năm 2016 của Chính phủ sửa đổi, bổ sung Nghị định số 150/2006/NĐ-CP ngày 12 tháng 12 năm 2006 quy định chi tiết và hướng dẫn thi hành một số điều Pháp lệnh Cựu chiến binh và Thông tư số 24/2009/TT-BLĐTBXH ngày 10 tháng 7 năm 2009 của Bộ trưởng Bộ Lao động - Thương binh và Xã hội hướng dẫn thực hiện Quyết định số 170/2008/QĐ-TTg ngày 18 tháng 12 năm 2008 của Thủ tướng Chính phủ về chế độ bảo hiểm y tế và trợ cấp mai táng đối với thanh niên xung phong thời kỳ kháng chiến chống Pháp','https://chinhphu.vn/?pageid=27160&docid=219657','https://datafiles.chinhphu.vn/cpp/files/vbpq/2026/9/21-bnv.signed.pdf','VBQPPL của Bộ',40,'thap','bhxh,hdld','','Từ khóa "bảo hiểm y tế" → Bảo hiểm xã hội (BHXH) · Thông tư (+10) · Cơ quan ban hành thuộc lĩnh vực tài chính / lao động (+10)','Sửa đổi chế độ cựu chiến binh','Văn bản sửa đổi, bổ sung chế độ, chính sách đối với cựu chiến binh, bao gồm bảo hiểm y tế. Văn bản này hướng dẫn thực hiện các quy định liên quan đến cựu chiến binh.','Cần đọc toàn văn để xác định ảnh hưởng đến các mục của cẩm nang liên quan đến bảo hiểm xã hội và lao động.','Nên đọc văn bản để hiểu rõ các thay đổi và điều chỉnh nếu doanh nghiệp có liên quan đến cựu chiến binh.','workers-ai:@cf/meta/llama-3.3-70b-instruct-fp8-fast','rejected',0,'',1791202673227,0,1791202673227,1791283738229,'','','reject','Chế độ cựu chiến binh – không liên quan');
