INSERT INTO "legal_docs" ("id","source","docid","so_hieu","loai","co_quan","ngay_ban_hanh","ngay_bh_iso","hieu_luc","trich_yeu","url","pdf_url","list_name","score","level","topics","matched","reasons","title","summary","impact","action","ai","status","in_handbook","admin_note","found_at","approved_at","created_at","updated_at","key_points","full_text","recommend","recommend_note") VALUES(130,'chinhphu','219330','43/2026/QH16','Nghị quyết','Quốc hội','24/08/2026','2026-08-24','24/08/2026 (áp dụng kỳ tính thuế 2026, 2027)','Về giảm thuế thu nhập cá nhân, thuế thu nhập doanh nghiệp đối với cá nhân và doanh nghiệp','https://chinhphu.vn/?pageid=27160&docid=219330','https://datafiles.chinhphu.vn/cpp/files/vbpq/2026/9/nq43vegiamthuetncntndn.signed.pdf','Quốc hội',75,'cao','tncn,tndn','','Từ khóa "thu nhập doanh nghiệp" → Thuế Thu nhập doanh nghiệp (TNDN) · Từ khóa "thu nhập cá nhân" → Thuế Thu nhập cá nhân (TNCN) · Từ khóa "giảm thuế" → Quản lý thuế chung · Luật / Nghị quyết Quốc hội (+20)','Giảm 30% thuế TNCN, TNDN năm 2026–2027 cho doanh nghiệp, cá nhân kinh doanh doanh thu không quá 10 tỷ đồng','Nghị quyết của Quốc hội giảm 30% số thuế TNCN (thu nhập từ kinh doanh của cá nhân cư trú) và 30% số thuế TNDN phải nộp của kỳ tính thuế 2026 và 2027, áp dụng khi doanh thu hằng năm không quá 10 tỷ đồng.','Đã bổ sung vào chủ đề Thuế TNCN và Thuế TNDN (thẻ văn bản 43/2026/QH16).','Kế toán xác định doanh thu năm 2026 để biết doanh nghiệp / hộ kinh doanh có thuộc diện giảm 30% không; theo dõi Nghị định hướng dẫn trước khi quyết toán năm 2026.','BuBu (đọc toàn văn)','approved',1,'',1791202673227,1791279817763,1791202673227,1791279817763,replace('Cá nhân cư trú có thu nhập từ kinh doanh, doanh thu năm 2026, 2027 không quá 10 tỷ đồng: giảm 30% số thuế TNCN phải nộp (Điều 1.1)\nDoanh nghiệp, tổ chức thành lập theo pháp luật Việt Nam, doanh thu năm 2026, 2027 không quá 10 tỷ đồng: giảm 30% số thuế TNDN phải nộp (Điều 1.2)\nKhông áp dụng cho doanh nghiệp hình thành từ chia, tách sau 24/08/2026 mà tổng doanh thu các doanh nghiệp sau chia, tách trên 10 tỷ đồng\nDoanh nghiệp đang hưởng ưu đãi thuế: mức giảm 30% tính trên số thuế phải nộp sau khi đã trừ ưu đãi\nHiệu lực từ 24/08/2026, áp dụng cho kỳ tính thuế 2026 và 2027; Chính phủ quy định chi tiết (Điều 2)','\n',char(10)),'','approve','Giảm 30% thuế TNCN, TNDN cho DN và cá nhân kinh doanh doanh thu ≤ 10 tỷ – ảnh hưởng rộng. Đã đọc toàn văn (bản Word); nội dung đã bổ sung vào chủ đề TNCN, TNDN của cẩm nang.');
