PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE tools (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slug TEXT NOT NULL UNIQUE,
  no TEXT NOT NULL DEFAULT '',
  name TEXT NOT NULL,
  grp TEXT NOT NULL DEFAULT 'vp',
  sub TEXT NOT NULL DEFAULT '',
  pain TEXT NOT NULL DEFAULT '',
  who TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'soon',
  price INTEGER NOT NULL DEFAULT 0,
  url TEXT NOT NULL DEFAULT '',
  embed INTEGER NOT NULL DEFAULT 0,
  videos TEXT NOT NULL DEFAULT '[]',
  body TEXT NOT NULL DEFAULT '',
  sort INTEGER NOT NULL DEFAULT 100,
  visible INTEGER NOT NULL DEFAULT 1,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
, pricing TEXT NOT NULL DEFAULT 'free', price_note TEXT NOT NULL DEFAULT '', featured INTEGER NOT NULL DEFAULT 0, icon TEXT NOT NULL DEFAULT '', tags TEXT NOT NULL DEFAULT '', features TEXT NOT NULL DEFAULT '', highlights TEXT NOT NULL DEFAULT '', guide TEXT NOT NULL DEFAULT '', version TEXT NOT NULL DEFAULT '', released TEXT NOT NULL DEFAULT '', author TEXT NOT NULL DEFAULT '', download_url TEXT NOT NULL DEFAULT '', banner_url TEXT NOT NULL DEFAULT '');
CREATE TABLE episodes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  no TEXT NOT NULL DEFAULT '',
  title TEXT NOT NULL,
  summary TEXT NOT NULL DEFAULT '',
  youtube_url TEXT NOT NULL DEFAULT '',
  shorts TEXT NOT NULL DEFAULT '[]',
  status TEXT NOT NULL DEFAULT 'draft',
  publish_date TEXT NOT NULL DEFAULT '',
  sort INTEGER NOT NULL DEFAULT 100,
  visible INTEGER NOT NULL DEFAULT 1,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE posts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  category TEXT NOT NULL DEFAULT 'quan-tri',
  excerpt TEXT NOT NULL DEFAULT '',
  body TEXT NOT NULL DEFAULT '',
  cover_url TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'draft',
  published_at TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE requests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  pain TEXT NOT NULL,
  role TEXT NOT NULL DEFAULT '',
  contact TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'new',
  votes INTEGER NOT NULL DEFAULT 1,
  tool_slug TEXT NOT NULL DEFAULT '',
  admin_note TEXT NOT NULL DEFAULT '',
  ip_hash TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE bookings (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  contact TEXT NOT NULL,
  topic TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'new',
  scheduled_at TEXT NOT NULL DEFAULT '',
  admin_note TEXT NOT NULL DEFAULT '',
  ip_hash TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE legal_docs (id INTEGER PRIMARY KEY AUTOINCREMENT, source TEXT NOT NULL DEFAULT 'chinhphu', docid TEXT NOT NULL,
    so_hieu TEXT NOT NULL DEFAULT '', loai TEXT NOT NULL DEFAULT '', co_quan TEXT NOT NULL DEFAULT '', ngay_ban_hanh TEXT NOT NULL DEFAULT '',
    ngay_bh_iso TEXT NOT NULL DEFAULT '', hieu_luc TEXT NOT NULL DEFAULT '', trich_yeu TEXT NOT NULL DEFAULT '', url TEXT NOT NULL DEFAULT '',
    pdf_url TEXT NOT NULL DEFAULT '', list_name TEXT NOT NULL DEFAULT '', score INTEGER NOT NULL DEFAULT 0, level TEXT NOT NULL DEFAULT '',
    topics TEXT NOT NULL DEFAULT '', matched TEXT NOT NULL DEFAULT '', reasons TEXT NOT NULL DEFAULT '', title TEXT NOT NULL DEFAULT '',
    summary TEXT NOT NULL DEFAULT '', impact TEXT NOT NULL DEFAULT '', action TEXT NOT NULL DEFAULT '', ai TEXT NOT NULL DEFAULT '',
    status TEXT NOT NULL DEFAULT 'pending', in_handbook INTEGER NOT NULL DEFAULT 0, admin_note TEXT NOT NULL DEFAULT '',
    found_at INTEGER NOT NULL DEFAULT 0, approved_at INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, key_points TEXT NOT NULL DEFAULT '', full_text TEXT NOT NULL DEFAULT '', recommend TEXT NOT NULL DEFAULT '', recommend_note TEXT NOT NULL DEFAULT '');
CREATE TABLE legal_scans (id INTEGER PRIMARY KEY AUTOINCREMENT, trigger TEXT NOT NULL DEFAULT '', started_at INTEGER NOT NULL,
    finished_at INTEGER NOT NULL DEFAULT 0, ok INTEGER NOT NULL DEFAULT 0, fetched INTEGER NOT NULL DEFAULT 0, new_count INTEGER NOT NULL DEFAULT 0,
    candidates INTEGER NOT NULL DEFAULT 0, ai TEXT NOT NULL DEFAULT '', error TEXT NOT NULL DEFAULT '', detail TEXT NOT NULL DEFAULT '');
CREATE TABLE feedback (id INTEGER PRIMARY KEY AUTOINCREMENT, tool_slug TEXT NOT NULL DEFAULT '', name TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '',
    content TEXT NOT NULL, page TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'new', admin_note TEXT NOT NULL DEFAULT '', ip_hash TEXT NOT NULL DEFAULT '',
    created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE subscribers (id INTEGER PRIMARY KEY AUTOINCREMENT, tool_slug TEXT NOT NULL DEFAULT '', email TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending',
    token TEXT NOT NULL DEFAULT '', consent_at INTEGER NOT NULL DEFAULT 0, confirmed_at INTEGER NOT NULL DEFAULT 0, last_sent_at INTEGER NOT NULL DEFAULT 0,
    admin_note TEXT NOT NULL DEFAULT '', ip_hash TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_requests_status ON requests(status, created_at);
CREATE INDEX idx_bookings_status ON bookings(status, created_at);
CREATE UNIQUE INDEX idx_legal_src_doc ON legal_docs(source, docid);
CREATE INDEX idx_legal_status ON legal_docs(status, ngay_bh_iso);
CREATE UNIQUE INDEX idx_subs_tool_email ON subscribers(tool_slug, email);
